function getBroadcastRecipients(scope?: BroadcastScope): AgentId[] {
  const agents = eventStore.listAgents({ state: 'running' });
  if (!scope || scope === 'all') return agents.map(a => a.id);
  return agents.filter(a => matchesScope(a.role, scope)).map(a => a.id);
}
