// In handleWorkerDone
async function handleWorkerDone(context: DoneContext): Promise<DoneResult> {
  const { agentId, workspace, dataplane } = context;

  // 1. Check for uncommitted changes
  if (workspace && hasUncommittedChanges(workspace.path)) {
    await commitUncommittedChanges(workspace.path, agentId);
