```typescript
class SudocodeTaskBackend implements TaskBackend {
  private eventStore: EventStore;
  private client: SudocodeClient;
  private tasksByIssue: Map<string, Set<TaskId>> = new Map();

  constructor(eventStore: EventStore, client: SudocodeClient) {
    this.eventStore = eventStore;
    this.client = client;
    this.rebuildIndex();
    this.subscribeToIssueChanges();
  }

  // ─── Read Operations ─────────────────────────────────────────
  async get(id: TaskId): Promise<Task | null> {
    const task = this.eventStore.getTask(id);
    if (!task) return null;
    return this.enrichTaskWithIssueData(task);
  }

  async list(filter?: TaskFilter): Promise<Task[]> {
    const tasks = this.eventStore.listTasks(filter);
    return Promise.all(tasks.map(t => this.enrichTaskWithIssueData(t)));
  }

  async listReady(): Promise<Task[]> {
    // Get ready issues from sudocode
    const readyIssues = await this.client.getReadyIssues();
    const readyIssueIds = new Set(readyIssues.map(i => i.id));

    // Filter tasks bound to ready issues
    const tasks = await this.list({ status: ['pending', 'assigned'] });
    return tasks.filter(t =>
      !t.external_id || readyIssueIds.has(t.external_id)
    );
  }

  private async enrichTaskWithIssueData(task: Task): Promise<Task> {
    if (!task.external_id) return task;

    const issue = await this.client.getIssue(task.external_id);
    if (!issue) {
      return { ...task, isBlocked: false };
    }

    const blockers = await this.client.getBlockers(task.external_id);
    const hasIncompleteBlockers = blockers.some(b => b.status !== 'closed');

    return {
      ...task,
      isBlocked: hasIncompleteBlockers,
      // Priority from issue if not set on task
    };
  }
}
```

