## Index Implementation

```typescript
class TaskIssueIndex {
  private tasksByIssue: Map<string, Set<TaskId>> = new Map();
  private issueByTask: Map<TaskId, string> = new Map();

  // Rebuild from EventStore on startup
  rebuild(eventStore: EventStore): void {
    this.tasksByIssue.clear();
    this.issueByTask.clear();

    const tasks = eventStore.listTasks({});
    for (const task of tasks) {
      if (task.external_id) {
        this.addBinding(task.id, task.external_id);
      }
    }
  }

  addBinding(taskId: TaskId, issueId: string): void {
    // Update issue -> tasks map
    if (!this.tasksByIssue.has(issueId)) {
      this.tasksByIssue.set(issueId, new Set());
    }
    this.tasksByIssue.get(issueId)!.add(taskId);

    // Update task -> issue map
    this.issueByTask.set(taskId, issueId);
  }

  removeBinding(taskId: TaskId): void {
    const issueId = this.issueByTask.get(taskId);
    if (issueId) {
      this.tasksByIssue.get(issueId)?.delete(taskId);
      this.issueByTask.delete(taskId);
    }
  }

  getTasksForIssue(issueId: string): TaskId[] {
    return Array.from(this.tasksByIssue.get(issueId) ?? []);
  }

  getIssueForTask(taskId: TaskId): string | undefined {
    return this.issueByTask.get(taskId);
  }
}
```

