private subscribeToIssueChanges(): void {
  this.client.onIssueChange((event) => {
    const boundTasks = this.index.getTasksForIssue(event.issueId);

    for (const taskId of boundTasks) {
      // Emit task change event for each bound task
      this.emitTaskChange({
        type: 'issue_changed',
        taskId,
        issueEvent: event,
      });
    }
  });
}
