// Bind task to issue
async bindToIssue(taskId: TaskId, issueId: string): Promise<void> {
  // Verify issue exists
  const issue = await this.client.getIssue(issueId);
  if (!issue) throw new Error(`Issue ${issueId} not found`);

  // Update task with external_id
  await this.eventStore.emitTaskEvent(taskId, {
    action: 'external_id_set',
    details: { external_id: issueId },
  });

  // Update index
  this.index.addBinding(taskId, issueId);
}

// Unbind task from issue
async unbindFromIssue(taskId: TaskId): Promise<void> {
  await this.eventStore.emitTaskEvent(taskId, {
    action: 'external_id_cleared',
    details: {},
  });
  this.index.removeBinding(taskId);
}
