## Implementation

```typescript
async function createSudocodeClient(config: SudocodeClientConfig): Promise<SudocodeClient> {
  if (config.mode === 'managed') {
    return new ServerClient({
      serverUrl: config.serverUrl!,
      wsUrl: config.wsUrl,
    });
  }

  if (config.mode === 'standalone') {
    return new StandaloneClient({
      projectPath: config.projectPath ?? process.cwd(),
    });
  }

  // Auto mode: detect server availability
  const serverAvailable = await checkServerHealth(
    config.autoDetect?.serverUrl ?? 'http://localhost:3001',
    config.autoDetect?.timeout ?? 2000
  );

  if (serverAvailable && config.autoDetect?.preferManaged !== false) {
    return new ServerClient({
      serverUrl: config.autoDetect?.serverUrl ?? 'http://localhost:3001',
    });
  }

  return new StandaloneClient({
    projectPath: config.projectPath ?? process.cwd(),
  });
}

async function checkServerHealth(serverUrl: string, timeout: number): Promise<boolean> {
  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);
    const response = await fetch(`${serverUrl}/health`, { signal: controller.signal });
    clearTimeout(timeoutId);
    return response.ok;
  } catch {
    return false;
  }
}
```

