async create(options: CreateTaskOptions): Promise<Task> {
  // 1. Create task in EventStore
  const task = await this.eventStore.createTask(options);

  // 2. If binding to issue, update index
  if (options.external_id) {
    await this.bindToIssue(task.id, options.external_id);
  }

  return this.enrichTaskWithIssueData(task);
}
```

