### start()
```typescript
async start(id: TaskId): Promise<void> {
  // 1. Update task status
  await this.eventStore.emitTaskEvent(id, {
    action: 'status_change',
    details: { status: 'in_progress' },
  });

  // 2. Update issue if configured
  const task = await this.get(id);
  if (task?.external_id && this.syncPolicy.updateIssueOnStart) {
    const issue = await this.client.getIssue(task.external_id);
    if (issue && issue.status === 'open') {
      await this.client.updateIssue(task.external_id, {
        status: 'in_progress',
      });
    }
  }
}
