## Summary

Implement the sync policy engine that handles bidirectional sync between tasks and issues based on configurable policies.

## SyncPolicy Interface

```typescript
interface SyncPolicy {
  // How to handle external issue closure
  onIssueClosed: 'complete_task' | 'fail_task' | 'notify_only';

  // How to handle description changes (default: 'snapshot')
  onDescriptionChanged: 'snapshot' | 'propagate';

  // How to handle blocker changes
  onBlockerChanged: 'update_blocked' | 'notify_only';

  // Whether to update issue status on task start
  updateIssueOnStart: boolean;

  // Whether to update issue status on task complete
  updateIssueOnComplete: 'never' | 'if_all_complete' | 'always';
}

const defaultSyncPolicy: SyncPolicy = {
  onIssueClosed: 'notify_only',
  onDescriptionChanged: 'snapshot',
  onBlockerChanged: 'update_blocked',
  updateIssueOnStart: true,
  updateIssueOnComplete: 'never',
};
```

## SyncPolicyEngine Implementation

```typescript
class SyncPolicyEngine {
  constructor(
    private policy: SyncPolicy,
    private backend: SudocodeTaskBackend,
    private eventEmitter: TaskEventEmitter
  ) {}

  async handleIssueChange(event: IssueChangeEvent): Promise<void> {
    const boundTasks = this.backend.getTasksForIssue(event.issueId);

    switch (event.type) {
      case 'deleted':
        await this.handleIssueDeleted(boundTasks, event);
        break;

      case 'status_changed':
        if (event.issue?.status === 'closed') {
          await this.handleIssueClosed(boundTasks, event);
        } else if (event.issue?.status === 'blocked') {
          await this.handleIssueBlocked(boundTasks, event);
        }
        break;

      case 'blocked':
        await this.handleBlockerAdded(boundTasks, event);
        break;

      case 'unblocked':
        await this.handleBlockerRemoved(boundTasks, event);
        break;

      case 'updated':
        await this.handleIssueUpdated(boundTasks, event);
        break;
    }
  }

  private async handleIssueClosed(tasks: TaskId[], event: IssueChangeEvent): Promise<void> {
    for (const taskId of tasks) {
      const task = await this.backend.get(taskId);
      if (!task || task.status === 'completed' || task.status === 'failed') continue;

      switch (this.policy.onIssueClosed) {
        case 'complete_task':
          await this.backend.complete(taskId, {
            reason: 'issue_closed_externally',
          });
          break;

        case 'fail_task':
          await this.backend.fail(taskId, {
            code: 'ISSUE_CLOSED',
            message: 'Bound issue was closed externally',
          });
          break;

        case 'notify_only':
          this.eventEmitter.emit({
            type: 'issue_closed',
            taskId,
            issueId: event.issueId,
          });
          break;
      }
    }
  }

  private async handleIssueDeleted(tasks: TaskId[], event: IssueChangeEvent): Promise<void> {
    // Always fail orphaned tasks
    for (const taskId of tasks) {
      const task = await this.backend.get(taskId);
      if (!task || task.status === 'completed' || task.status === 'failed') continue;

      await this.backend.fail(taskId, {
        code: 'ISSUE_DELETED',
        message: `Bound issue ${event.issueId} was deleted`,
      });
    }
  }

  private async handleBlockerAdded(tasks: TaskId[], event: IssueChangeEvent): Promise<void> {
    if (this.policy.onBlockerChanged === 'update_blocked') {
      // isBlocked will be recomputed on next get()
      // Emit notification for active tasks
      for (const taskId of tasks) {
        this.eventEmitter.emit({
          type: 'blocker_added',
          taskId,
          issueId: event.issueId,
        });
      }
    }
  }
}
```

