## Summary

Implement TaskBackend dependency operations that use sudocode's relationship system for blockers.

## Dependency Operations

### addBlocker()
```typescript
async addBlocker(taskId: TaskId, blockerId: TaskId): Promise<void> {
  const task = await this.get(taskId);
  const blocker = await this.get(blockerId);

  if (!task || !blocker) {
    throw new Error('Task or blocker not found');
  }

  // If both tasks are bound to issues, create sudocode relationship
  if (task.external_id && blocker.external_id) {
    await this.client.createLink(
      blocker.external_id,  // from (blocker)
      task.external_id,     // to (blocked task)
      'blocks'
    );
  } else {
    // For unbound tasks, use EventStore blocker tracking
    await this.eventStore.emitTaskEvent(taskId, {
      action: 'blocker_added',
      details: { blocker_id: blockerId },
    });
  }
}
```

### removeBlocker()
```typescript
async removeBlocker(taskId: TaskId, blockerId: TaskId): Promise<void> {
  const task = await this.get(taskId);
  const blocker = await this.get(blockerId);

  if (task?.external_id && blocker?.external_id) {
    await this.client.removeLink(
      blocker.external_id,
      task.external_id,
      'blocks'
    );
  } else {
    await this.eventStore.emitTaskEvent(taskId, {
      action: 'blocker_removed',
      details: { blocker_id: blockerId },
    });
  }
}
```

### getBlockers()
```typescript
async getBlockers(taskId: TaskId): Promise<Task[]> {
  const task = await this.get(taskId);
  if (!task) return [];

  if (task.external_id) {
    // Get blockers from sudocode
    const issues = await this.client.getBlockers(task.external_id);

    // Find tasks bound to these issues
    const tasks: Task[] = [];
    for (const issue of issues) {
      const boundTaskIds = this.index.getTasksForIssue(issue.id);
      for (const tid of boundTaskIds) {
        const t = await this.get(tid);
        if (t) tasks.push(t);
      }
    }
    return tasks;
  } else {
    // Get blockers from EventStore
    const blockerIds = task.blockers ?? [];
    return Promise.all(
      blockerIds.map(id => this.get(id)).filter(Boolean)
    );
  }
}
```

### getBlocking()
```typescript
async getBlocking(taskId: TaskId): Promise<Task[]> {
  const task = await this.get(taskId);
  if (!task) return [];

  if (task.external_id) {
    // Get issues this task's issue blocks
    const issues = await this.client.getBlocking(task.external_id);

    // Find tasks bound to these issues
    const tasks: Task[] = [];
    for (const issue of issues) {
      const boundTaskIds = this.index.getTasksForIssue(issue.id);
      for (const tid of boundTaskIds) {
        const t = await this.get(tid);
        if (t) tasks.push(t);
      }
    }
    return tasks;
  } else {
    // Scan all tasks for those blocked by this task
    const allTasks = await this.list({});
    return allTasks.filter(t =>
      t.blockers?.includes(taskId)
    );
  }
}
```

