Implement `SudocodeTaskToolProvider` that exposes MCP tools for task operations. Default mode is 'native' which exposes sudocode's native issue tools.

## TaskToolProvider Interface

```typescript
interface TaskToolProvider {
  // Returns the MCP tools to expose for task operations
  getTools(): MCPToolDefinition[];

  // Tools that should NOT be exposed when this provider is active
  getExcludedTools?(): string[];
}
```

## SudocodeTaskToolProvider Implementation

```typescript
class SudocodeTaskToolProvider implements TaskToolProvider {
  constructor(
    private backend: SudocodeTaskBackend,
    private client: SudocodeClient,
    private mode: 'native' | 'mapped' | 'both' = 'native'
  ) {}

  getTools(): MCPToolDefinition[] {
    if (this.mode === 'native') {
      return this.getNativeTools();
    } else if (this.mode === 'mapped') {
      return this.getMappedTools();
    } else {
      return [...this.getNativeTools(), ...this.getMappedTools()];
    }
  }

  getExcludedTools(): string[] {
    if (this.mode === 'native') {
      // Exclude generic task tools when using native issue tools
      return ['create_task', 'get_task', 'update_task', 'list_tasks'];
    }
    return [];
  }

  private getNativeTools(): MCPToolDefinition[] {
    // Expose sudocode's native MCP tools
    // These are pass-through to sudocode MCP
    return [
      {
        name: 'upsert_issue',
        description: 'Create or update a sudocode issue',
        schema: { /* ... */ },
        handler: async (params) => {
          return this.client.updateIssue(params.issue_id, params);
        },
      },
      {
        name: 'show_issue',
        description: 'Get issue details',
        schema: { /* ... */ },
        handler: async (params) => {
          return this.client.getIssue(params.issue_id);
        },
      },
      {
        name: 'list_issues',
        description: 'List and filter issues',
        schema: { /* ... */ },
        handler: async (params) => {
          return this.client.listIssues(params);
        },
      },
      {
        name: 'ready',
        description: 'Get ready issues (no blockers)',
        schema: { /* ... */ },
        handler: async () => {
          return this.client.getReadyIssues();
        },
      },
      {
        name: 'link',
        description: 'Create relationship between issues/specs',
        schema: { /* ... */ },
        handler: async (params) => {
          return this.client.createLink(params.from_id, params.to_id, params.type);
        },
      },
    ];
  }

  private getMappedTools(): MCPToolDefinition[] {
    // Generic task tools that map to sudocode operations
    return [
      {
        name: 'create_task',
        description: 'Create a task (optionally bound to issue)',
        schema: { /* ... */ },
        handler: async (params) => {
          return this.backend.create(params);
        },
      },
      {
        name: 'get_task',
        description: 'Get task by ID',
        schema: { /* ... */ },
        handler: async (params) => {
          return this.backend.get(params.task_id);
        },
      },
      {
        name: 'list_ready_tasks',
        description: 'List tasks ready for work',
        schema: { /* ... */ },
        handler: async (params) => {
          return this.backend.listReady(params);
        },
      },
      {
        name: 'get_task_blockers',
        description: 'Get tasks blocking this task',
        schema: { /* ... */ },
        handler: async (params) => {
          return this.backend.getBlockers(params.task_id);
        },
      },
    ];
  }
}
```

