```typescript
// In macro-agent configuration
interface MacroAgentConfig {
  taskBackend: TaskBackendConfig;
  taskToolMode: TaskToolMode;
}

type TaskBackendConfig =
  | { type: 'memory' }
  | { type: 'sudocode'; config: SudocodeBackendConfig };

// Factory function
async function createTaskBackend(config: TaskBackendConfig): Promise<TaskBackend> {
  if (config.type === 'memory') {
    return new InMemoryTaskBackend(eventStore);
  }

  if (config.type === 'sudocode') {
    const client = await createSudocodeClient(config.config);
    return new SudocodeTaskBackend(eventStore, client, config.config);
  }

  throw new Error(`Unknown backend type: ${config.type}`);
}
```

### Tool Provider Registration

```typescript
// In MCP server setup
function setupMcpServer(backend: TaskBackend, config: MacroAgentConfig): MCPServer {
  const server = new MCPServer();

  // Get tool provider from backend
  const toolProvider = backend.getToolProvider?.(config.taskToolMode);

  if (toolProvider) {
    // Register tools from provider
    for (const tool of toolProvider.getTools()) {
      server.registerTool(tool);
    }

    // Exclude conflicting tools
    const excluded = toolProvider.getExcludedTools?.() ?? [];
    for (const toolName of excluded) {
      server.excludeTool(toolName);
    }
  } else {
    // Default task tools for backends without custom provider
    server.registerTool(createTaskTool);
    server.registerTool(getTaskTool);
    // ...
  }

  return server;
}
```

