```typescript
export const injectContextTool = {
  name: "inject_context",
  description: `Inject context into another agent's session. Use this for time-sensitive 
steering that can't wait for the agent to check messages. The context will appear 
in the target agent's next turn (or immediately if urgent).

Fallback behavior:
- If injection not supported, falls back to interrupting the agent
- If interruption not allowed, falls back to sending a high-priority message`,

  inputSchema: {
    type: "object",
    properties: {
      target_agent_id: {
        type: "string",
        description: "The agent ID to inject context into"
      },
      content: {
        type: "string", 
        description: "The context message to inject"
      },
      urgent: {
        type: "boolean",
        description: "If true, interrupts current work immediately",
        default: false
      },
      reason: {
        type: "string",
        description: "Optional reason for the injection (for audit logs)"
      }
    },
    required: ["target_agent_id", "content"]
  }
};
```

**Handler:**
```typescript
async function handleInjectContext(
  args: { target_agent_id: string; content: string; urgent?: boolean; reason?: string },
  context: { agentId: AgentId; agentManager: AgentManager; messageRouter: MessageRouter }
): Promise<ToolResult> {
  const result = await injectContext(
    context.agentManager,
    context.messageRouter,
    args.target_agent_id,
    args.content,
    {
      urgent: args.urgent,
      allowInterrupt: true,  // MCP tool always allows interrupt fallback
      source: { type: "agent", agentId: context.agentId }
    }
  );

  return {
    content: [{
      type: "text",
      text: result.success
        ? `Context injected via ${result.method}${result.note ? `: ${result.note}` : ""}`
        : `Injection failed: ${result.error}`
    }],
    isError: !result.success
  };
}
```

