export interface InjectionOptions {
  /** Allow falling back to interruptWith if inject fails */
  allowInterrupt?: boolean;
  /** Force interrupt even if inject is available */
  urgent?: boolean;
  /** Source of injection for audit */
  source?: InjectionSource;
}

export type InjectionSource =
  | { type: "human" }
  | { type: "agent"; agentId: AgentId };

export type InjectionMethod = "inject" | "interrupt" | "message" | "queued";

export interface InjectionResult {
  success: boolean;
  method?: InjectionMethod;
  error?: string;
  note?: string;
}
```

### Core Function (`src/steering/inject.ts`)

```typescript
export async function injectContext(
  agentManager: AgentManager,
  messageRouter: MessageRouter,
  targetAgentId: AgentId,
  content: string,
  options: InjectionOptions = {}
): Promise<InjectionResult>
```

**Fallback chain:**
1. Check if agent has session via `agentManager.getSession()`
2. If `urgent`, prefer `interruptWith()`
3. Try `session.inject()` if supported
4. Fall back to `session.interruptWith()` if `allowInterrupt`
5. Fall back to high-priority message via `messageRouter.send()`

