  stoppedAt: Timestamp;
  acpSessionId: string;
  reason: 'done_called' | 'parent_terminated';
}

interface StallDetectorConfig {
  stalledThresholdMs: number; // Default: 600000 (10 min)
}

class StallDetector {
  constructor(
    eventStore: EventStore,
    sessionMapper: SessionMapper,
    config: StallDetectorConfig
  );

  /** Detect stalled workers under a coordinator */
  detectStalled(coordinatorId: AgentId): StalledAgent[];

  /** Detect and clean up zombie agents */
  cleanupZombies(): Promise<ZombieAgent[]>;
}
```

## Detection Logic

**Stalled:** 
- `now - lastActivityAt > stalledThresholdMs`
- AND `!sessionStatus.isProcessing`

**Zombie:**
- `agent.state === 'stopped'`
- AND session still exists in SessionMapper
- Action: Remove the session mapping

